"use client"

import type { BookPreviewContentsEntry } from "./types"

export type PdfTextItem = { str?: string }
export type PdfTextContent = { items: PdfTextItem[] }

export type PdfPageProxy = {
  getViewport: (options: { scale: number }) => { width: number; height: number }
  getTextContent?: () => Promise<PdfTextContent>
  render: (options: {
    canvasContext: CanvasRenderingContext2D
    viewport: { width: number; height: number }
    transform?: number[]
  }) => { promise: Promise<void>; cancel: () => void }
}

export type PdfDestinationRef = { num: number; gen: number }

export type PdfOutlineNode = {
  title?: string
  dest?: string | unknown[] | null
  items?: PdfOutlineNode[] | null
}

export type PdfDocumentProxy = {
  numPages: number
  getPage: (pageNumber: number) => Promise<PdfPageProxy>
  getOutline?: () => Promise<PdfOutlineNode[] | null>
  getDestination?: (id: string) => Promise<unknown[] | null>
  getPageIndex?: (ref: PdfDestinationRef) => Promise<number>
}

export type PdfLoadResult = {
  task: { destroy: () => Promise<void> }
  doc: PdfDocumentProxy
}

export type PdfSource = string | { data: ArrayBuffer }

export async function loadPdfDocument(src: PdfSource): Promise<PdfLoadResult> {
  const pdfjs = await import("pdfjs-dist")
  if (!pdfjs.GlobalWorkerOptions.workerSrc && !pdfjs.GlobalWorkerOptions.workerPort) {
    pdfjs.GlobalWorkerOptions.workerSrc = new URL(
      "pdfjs-dist/build/pdf.worker.min.mjs",
      import.meta.url
    ).toString()
  }
  const source = typeof src === "string" ? { url: src } : src
  const task = pdfjs.getDocument(source)
  const doc = (await task.promise) as unknown as PdfDocumentProxy
  return { task, doc }
}

// Uncapped devicePixelRatio turns a page into a ~30MP canvas on 3x phones;
// past 2x the extra pixels are invisible while reading.
const PDF_MAX_RENDER_DPR = 2

function defaultPixelRatio(): number {
  if (typeof window === "undefined") return 1
  return Math.min(PDF_MAX_RENDER_DPR, Math.max(1, window.devicePixelRatio || 1))
}

export function renderPdfPageToCanvas(input: {
  page: PdfPageProxy
  canvas: HTMLCanvasElement
  scale: number
  pixelRatio?: number
}): { promise: Promise<void>; cancel: () => void } {
  const pixelRatio = input.pixelRatio ?? defaultPixelRatio()
  const viewport = input.page.getViewport({ scale: input.scale })
  const context = input.canvas.getContext("2d")
  if (!context) {
    throw new Error("Could not create a canvas for this PDF page.")
  }
  input.canvas.width = Math.max(1, Math.floor(viewport.width * pixelRatio))
  input.canvas.height = Math.max(1, Math.floor(viewport.height * pixelRatio))
  input.canvas.style.width = `${Math.floor(viewport.width)}px`
  input.canvas.style.height = `${Math.floor(viewport.height)}px`
  const transform = pixelRatio === 1 ? undefined : [pixelRatio, 0, 0, pixelRatio, 0, 0]
  return input.page.render({ canvasContext: context, viewport, transform })
}

/**
 * Plain text of a page, for search and speech.
 *
 * This is deliberately separate from the selectable text layer below. A curl
 * sheet is mid-flight 3D-transformed and cloned outside React, so putting
 * real selectable spans on it would break selection and cost a layer per
 * page. Paged curl reading wants *findable* text; only the flat reader wants
 * *selectable* text.
 */
export async function extractPdfPageText(page: PdfPageProxy): Promise<string> {
  if (typeof page.getTextContent !== "function") return ""
  try {
    const content = await page.getTextContent()
    return content.items
      .map((item) => item.str ?? "")
      .join(" ")
      .replace(/\s+/g, " ")
      .trim()
  } catch {
    // An image-only or malformed page simply has no text.
    return ""
  }
}

/**
 * Renders a real, selectable text layer over an already-painted canvas.
 * The container must be positioned and exactly overlay the canvas box.
 */
export async function renderPdfTextLayer(input: {
  page: PdfPageProxy
  container: HTMLElement
  scale: number
}): Promise<{ cancel: () => void }> {
  if (typeof input.page.getTextContent !== "function") {
    return { cancel: () => {} }
  }
  const pdfjs = await import("pdfjs-dist")
  const viewport = input.page.getViewport({ scale: input.scale })
  const textContentSource = await input.page.getTextContent()
  const layer = new pdfjs.TextLayer({
    textContentSource: textContentSource as never,
    container: input.container,
    viewport: viewport as never,
  })
  await layer.render()
  return { cancel: () => layer.cancel() }
}

/** Intrinsic aspect ratio (height / width) of a page at scale 1. */
export function pdfPageAspectRatio(page: PdfPageProxy): number {
  const base = page.getViewport({ scale: 1 })
  if (!(base.width > 0) || !(base.height > 0)) return Math.SQRT2
  return base.height / base.width
}

function canvasToObjectUrl(canvas: HTMLCanvasElement): Promise<string> {
  return new Promise((resolve) => {
    // Blob URLs keep the bitmap out of the JS heap. A base64 data URL of the
    // same page is ~33% larger and is copied again by every DOM clone the
    // flip book makes, so it is only the fallback.
    if (typeof canvas.toBlob !== "function") {
      resolve(canvas.toDataURL("image/png"))
      return
    }
    canvas.toBlob((blob) => {
      resolve(blob ? URL.createObjectURL(blob) : canvas.toDataURL("image/png"))
    }, "image/png")
  })
}

/** Release a URL produced by `rasterizePdfPage`. Safe for data-URL fallbacks. */
export function releaseRasterUrl(src: string | undefined | null): void {
  if (!src || !src.startsWith("blob:")) return
  try {
    URL.revokeObjectURL(src)
  } catch {
    // Already revoked, or the document is being torn down.
  }
}

// A document outline can nest arbitrarily deep; the contents menu only needs
// a few levels of indentation, and a malformed file should never grow the
// menu without bound.
const OUTLINE_MAX_ENTRIES = 300
const OUTLINE_MAX_DEPTH = 4

function outlineDestinationRef(dest: PdfOutlineNode["dest"]): PdfDestinationRef | string | null {
  if (typeof dest === "string") return dest
  if (Array.isArray(dest)) {
    const first = dest[0] as Partial<PdfDestinationRef> | null | undefined
    if (first && typeof first.num === "number") return first as PdfDestinationRef
  }
  return null
}

/**
 * Reads the document outline ("bookmarks") into flat contents entries for the
 * toolbar menu. Entries without a resolvable page destination are dropped —
 * external links and action bookmarks have nowhere in the reader to go.
 */
export async function resolvePdfOutline(
  doc: PdfDocumentProxy
): Promise<BookPreviewContentsEntry[]> {
  if (typeof doc.getOutline !== "function" || typeof doc.getPageIndex !== "function") {
    return []
  }
  let outline: PdfOutlineNode[] | null
  try {
    outline = await doc.getOutline()
  } catch {
    return []
  }
  if (!outline || outline.length === 0) return []

  const flat: { title: string; depth: number; ref: PdfDestinationRef | string | null }[] = []
  const walk = (nodes: PdfOutlineNode[], depth: number) => {
    for (const node of nodes) {
      if (flat.length >= OUTLINE_MAX_ENTRIES) return
      const title = node.title?.trim()
      if (title) {
        flat.push({ title, depth: Math.min(depth, OUTLINE_MAX_DEPTH), ref: outlineDestinationRef(node.dest) })
      }
      if (node.items && node.items.length > 0) walk(node.items, depth + 1)
    }
  }
  walk(outline, 0)

  const entries = await Promise.all(
    flat.map(async (item) => {
      if (!item.ref) return null
      try {
        const ref =
          typeof item.ref === "string"
            ? outlineDestinationRef(((await doc.getDestination?.(item.ref)) ?? null) as PdfOutlineNode["dest"])
            : item.ref
        if (!ref || typeof ref === "string") return null
        const pageIndex = await doc.getPageIndex!(ref)
        if (!Number.isFinite(pageIndex) || pageIndex < 0 || pageIndex >= doc.numPages) return null
        return { title: item.title, pageIndex, depth: item.depth }
      } catch {
        return null
      }
    })
  )
  return entries.filter((entry): entry is BookPreviewContentsEntry => entry !== null)
}

export async function rasterizePdfPage(input: {
  page: PdfPageProxy
  cssWidth: number
  cssHeight: number
  pixelRatio?: number
}): Promise<{ src: string; width: number; height: number }> {
  const pixelRatio = input.pixelRatio ?? defaultPixelRatio()
  const base = input.page.getViewport({ scale: 1 })
  const fit = Math.min(input.cssWidth / base.width, input.cssHeight / base.height)
  const viewport = input.page.getViewport({ scale: fit })
  const canvas = document.createElement("canvas")
  await renderPdfPageToCanvas({
    page: input.page,
    canvas,
    scale: fit,
    pixelRatio,
  }).promise
  const src = await canvasToObjectUrl(canvas)
  // Drop the backing store now that the bitmap is encoded; Safari keeps large
  // canvases alive well past the last reference otherwise.
  canvas.width = 0
  canvas.height = 0
  return {
    src,
    width: Math.floor(viewport.width),
    height: Math.floor(viewport.height),
  }
}

"use client"

import { useEffect, useRef, useState } from "react"
import {
  extractPdfPageText,
  loadPdfDocument,
  pdfPageAspectRatio,
  rasterizePdfPage,
  releaseRasterUrl,
} from "../pdf-runtime"
import type { BookPreviewError } from "../types"

export type PdfSheet = {
  id: string
  src: string
  width: number
  height: number
  /** Plain page text, when extraction is enabled. Empty for image-only pages. */
  text: string
}

type UsePdfSheetsOptions = {
  pdfUrl: string | undefined
  /** False for page-backed sources; the hook then does no work at all. */
  enabled: boolean
  /** Rasterization is reordered so the page being read paints first. */
  pageIndex: number
  rasterWidth: number
  /**
   * "uniform" sizes every sheet to page 1's aspect ratio, which is what a
   * bound book needs -- leaves cannot each be a different shape. "per-page"
   * measures each page, for continuous scrolling.
   */
  sizing: "uniform" | "per-page"
  /** Pull plain text per page so the reader can search and speak a PDF. */
  extractText?: boolean
  /**
   * Bound live rasters to +/- this many pages around the reading position.
   * Pages that fall outside are revoked and re-render on return, so a long
   * document holds ~2*windowRadius+1 decoded bitmaps instead of all of them.
   * Omit for engines that must keep every sheet painted (the curl flip book
   * owns all leaves at once).
   */
  windowRadius?: number
  /**
   * Fail with `maxPagesMessage` when the document exceeds this page count.
   * For engines that hold every raster at once, a page-flip of a 400-page
   * file is a hang, not a feature — they should point the reader at a
   * bounded mode instead of starting work.
   */
  maxPages?: number
  maxPagesMessage?: string
  onError: (error: BookPreviewError) => void
  errorMessage: string
}

type UsePdfSheetsResult = {
  sheets: PdfSheet[] | null
  /** height / width of page 1, once known. Null until the document opens. */
  ratio: number | null
  prepared: number
  preparing: boolean
}

/**
 * Opens a PDF and rasterizes its pages into image sheets.
 *
 * Every sheet is mounted up front with an empty src so the reader knows the
 * page count immediately and stays usable while pages fill in behind it.
 * Rasters are object URLs, released together when the document is torn down --
 * they cannot be released per sheet, because the curl engine clones the <img>
 * nodes into a flip book that React does not own.
 */
export function usePdfSheets({
  pdfUrl,
  enabled,
  pageIndex,
  rasterWidth,
  sizing,
  extractText = false,
  windowRadius,
  maxPages,
  maxPagesMessage,
  onError,
  errorMessage,
}: UsePdfSheetsOptions): UsePdfSheetsResult {
  // Sheets are keyed to the url that produced them: when pdfUrl changes the
  // stale document stops matching the gate below, so no effect-body reset is
  // needed and a superseded load can never publish its pages.
  const [doc, setDoc] = useState<{
    url: string
    ratio: number | null
    sheets: PdfSheet[] | null
  } | null>(null)
  const priorityRef = useRef(pageIndex + 1)
  const wakeRef = useRef<(() => void) | null>(null)
  const reportError = useRef(onError)
  const message = useRef(errorMessage)

  useEffect(() => {
    priorityRef.current = pageIndex + 1
    reportError.current = onError
    message.current = errorMessage
    // Resume a parked windowed drain — the new reading position may need
    // pages the loop skipped.
    wakeRef.current?.()
  })

  useEffect(() => {
    if (!enabled || !pdfUrl) return
    let cancelled = false
    let loaded: Awaited<ReturnType<typeof loadPdfDocument>> | null = null
    let uniformHeight = 0
    let pixelRatio = 1
    // Live rasters by page number; doubles as the teardown revocation list.
    const rendered = new Map<number, string>()
    // Pages already tried — attempted failures stay blank rather than
    // re-failing on every pass, matching the old once-only queue.
    const attempted = new Set<number>()

    const inWindow = (pageNumber: number, priority: number): boolean =>
      windowRadius === undefined || Math.abs(pageNumber - priority) <= windowRadius

    // Pages commit through this guarded writer. It stays a flat async
    // function — not a loop body — so each post-await state write is provably
    // dominated by a cancellation check.
    async function renderSheet(url: string, pageNumber: number): Promise<void> {
      if (cancelled || !loaded) return
      attempted.add(pageNumber)
      try {
        const page = await loaded.doc.getPage(pageNumber)
        // Text first: it is cheap, and it makes the page findable before
        // its bitmap has finished painting.
        const text = extractText ? await extractPdfPageText(page) : ""
        if (cancelled) return
        const cssHeight =
          sizing === "uniform"
            ? uniformHeight
            : Math.round(rasterWidth * pdfPageAspectRatio(page))
        const raster = await rasterizePdfPage({
          page,
          cssWidth: rasterWidth,
          cssHeight,
          pixelRatio,
        })
        if (cancelled) {
          releaseRasterUrl(raster.src)
          return
        }
        const previous = rendered.get(pageNumber)
        if (previous) releaseRasterUrl(previous)
        rendered.set(pageNumber, raster.src)
        const id = `pdf-${pageNumber}`
        setDoc(
          (current) =>
            current && current.url === url && current.sheets
              ? {
                  ...current,
                  sheets: current.sheets.map((sheet) =>
                    sheet.id === id
                      ? {
                          ...sheet,
                          src: raster.src,
                          width: raster.width,
                          height: raster.height,
                          text,
                        }
                      : sheet
                  ),
                }
              : current
        )
      } catch {
        // A single bad page stays blank instead of failing the document.
      }
    }

    // Revokes rasters that fell behind the reading position. The extracted
    // text stays — it is small — so a pruned page re-renders its bitmap only.
    function prune(url: string, priority: number): void {
      if (windowRadius === undefined) return
      for (const [pageNumber, src] of rendered) {
        if (inWindow(pageNumber, priority)) continue
        rendered.delete(pageNumber)
        attempted.delete(pageNumber)
        releaseRasterUrl(src)
        const id = `pdf-${pageNumber}`
        setDoc((current) =>
          current && current.url === url && current.sheets
            ? {
                ...current,
                sheets: current.sheets.map((sheet) =>
                  sheet.id === id ? { ...sheet, src: "" } : sheet
                ),
              }
            : current
        )
      }
    }

    // Nearest unrendered page to the reading position, expanding outward —
    // a reader at page 50 gets 50, 51, 49, 52, 48… instead of waiting for
    // everything before it.
    function pickNext(priority: number, count: number): number | undefined {
      if (!attempted.has(priority) && priority <= count) return priority
      for (let distance = 1; distance < count; distance += 1) {
        if (windowRadius !== undefined && distance > windowRadius) break
        const before = priority - distance
        const after = priority + distance
        if (before >= 1 && inWindow(before, priority) && !attempted.has(before)) {
          return before
        }
        if (after <= count && inWindow(after, priority) && !attempted.has(after)) {
          return after
        }
        if (before < 1 && after > count) break
      }
      return undefined
    }

    // One sequential worker per document. Without a window it ends when every
    // page is painted; with a window it parks when the visible range is done
    // and the priority effect above wakes it on the next page turn.
    async function drain(url: string): Promise<void> {
      const count = loaded?.doc.numPages ?? 0
      while (!cancelled && loaded) {
        const priority = Math.min(Math.max(1, priorityRef.current), count)
        prune(url, priority)
        const next = pickNext(priority, count)
        if (next === undefined) {
          if (windowRadius === undefined) return
          await new Promise<void>((resolve) => {
            wakeRef.current = resolve
          })
          wakeRef.current = null
          continue
        }
        await renderSheet(url, next)
      }
    }

    async function open(url: string) {
      try {
        const result = await loadPdfDocument(url)
        loaded = result
        if (cancelled) {
          await result.task.destroy()
          return
        }
        const count = result.doc.numPages
        if (maxPages !== undefined && count > maxPages) {
          loaded = null
          await result.task.destroy()
          if (!cancelled) {
            reportError.current({
              kind: "pdf-render",
              message: maxPagesMessage ?? message.current,
            })
          }
          return
        }
        // A 960px sheet at 2x is already roughly a 4MP bitmap. Capping DPR
        // avoids turning high-density phones into a large memory multiplier.
        pixelRatio =
          typeof window === "undefined" ? 1 : Math.min(2, Math.max(1, window.devicePixelRatio || 1))

        const firstPage = await result.doc.getPage(1)
        if (cancelled) return
        const baseRatio = pdfPageAspectRatio(firstPage)
        uniformHeight = Math.round(rasterWidth * baseRatio)

        setDoc({
          url,
          ratio: baseRatio,
          sheets: Array.from({ length: count }, (_, index) => ({
            id: `pdf-${index + 1}`,
            src: "",
            width: rasterWidth,
            height: uniformHeight,
            text: "",
          })),
        })

        await drain(url)
      } catch {
        if (!cancelled) {
          reportError.current({ kind: "pdf-render", message: message.current })
        }
      }
    }

    void open(pdfUrl)
    return () => {
      cancelled = true
      // Unpark the drain so it sees `cancelled` and exits.
      wakeRef.current?.()
      wakeRef.current = null
      if (loaded) void loaded.task.destroy()
      for (const src of rendered.values()) releaseRasterUrl(src)
      rendered.clear()
    }
  }, [enabled, pdfUrl, rasterWidth, sizing, extractText, windowRadius, maxPages, maxPagesMessage])

  const active = enabled && pdfUrl && doc?.url === pdfUrl ? doc : null
  const activeSheets = active?.sheets ?? null
  const prepared = activeSheets?.filter((sheet) => sheet.src).length ?? 0
  // With a window, "preparing" means the visible range still has gaps — far
  // pages staying blank is the intended steady state, not ongoing work.
  const pendingInWindow =
    activeSheets?.some(
      (sheet, index) =>
        !sheet.src &&
        (windowRadius === undefined ||
          Math.abs(index + 1 - (pageIndex + 1)) <= windowRadius)
    ) ?? false
  return {
    sheets: activeSheets,
    ratio: active?.ratio ?? null,
    prepared,
    preparing: enabled && activeSheets !== null && pendingInWindow,
  }
}

"use client"

import { Badge } from "@/components/ui/badge"
import { Spinner } from "@/components/ui/spinner"

/**
 * Progress while a PDF rasterizes. Uses the shared Badge primitive rather than
 * a bespoke pill so it tracks the design system automatically.
 */
export function PdfPreparingBadge({ prepared, total }: { prepared: number; total: number }) {
  return (
    <Badge
      role="status"
      variant="outline"
      data-book-preview-fade
      className="pointer-events-none absolute bottom-3 left-1/2 -translate-x-1/2 gap-1.5 bg-card/90 font-mono text-muted-foreground shadow-sm backdrop-blur"
    >
      <Spinner data-icon="inline-start" />
      {prepared}/{total}
    </Badge>
  )
}

"use client"

import { useEffect, useRef, useState, type RefObject } from "react"
import { cn } from "@/lib/utils"
import {
  pdfPageAspectRatio,
  rasterizePdfPage,
  releaseRasterUrl,
  type PdfDocumentProxy,
} from "../pdf-runtime"

const THUMB_WIDTH = 96
// Render a thumb only when it nears the rail viewport — a 300-page document
// must not queue 300 rasters just because the rail opened once.
const THUMB_ROOT_MARGIN = "240px"

/**
 * Lazily rasterizes page thumbnails for the rail. Work is requested by an
 * IntersectionObserver as each placeholder nears view, rendered one at a
 * time, and cached in state — a thumb is ~60KB, so the cache stays small
 * even on long documents. All URLs are revoked when the rail unmounts or
 * the document changes.
 */
function usePdfThumbnails({
  doc,
  railRef,
}: {
  doc: PdfDocumentProxy
  railRef: RefObject<HTMLDivElement | null>
}) {
  const [thumbs, setThumbs] = useState<Map<number, string>>(new Map())

  // A different document must never show the previous file's bitmaps; the
  // effect below revokes their URLs at the same time.
  const [prevDoc, setPrevDoc] = useState(doc)
  if (prevDoc !== doc) {
    setPrevDoc(doc)
    setThumbs(new Map())
  }

  useEffect(() => {
    const rendered = new Map<number, string>()
    const queue: number[] = []
    const queued = new Set<number>()
    let cancelled = false
    let working = false

    const pump = async () => {
      if (working) return
      working = true
      while (!cancelled) {
        const next = queue.shift()
        if (next === undefined) break
        try {
          const page = await doc.getPage(next)
          const ratio = pdfPageAspectRatio(page)
          const raster = await rasterizePdfPage({
            page,
            cssWidth: THUMB_WIDTH,
            cssHeight: Math.round(THUMB_WIDTH * ratio),
            // Thumbs are decorative navigation — 1x is plenty and keeps the
            // worker free for the page the reader is actually looking at.
            pixelRatio: 1,
          })
          if (cancelled) {
            releaseRasterUrl(raster.src)
            break
          }
          rendered.set(next, raster.src)
          setThumbs(new Map(rendered))
        } catch {
          // A failed thumb stays a skeleton; it does not block the queue.
        }
      }
      working = false
    }

    const request = (page: number) => {
      if (rendered.has(page) || queued.has(page)) return
      queued.add(page)
      queue.push(page)
      void pump()
    }

    const rail = railRef.current
    let observer: IntersectionObserver | null = null
    if (rail && typeof IntersectionObserver !== "undefined") {
      observer = new IntersectionObserver(
        (entries) => {
          for (const entry of entries) {
            if (!entry.isIntersecting) continue
            const page = Number((entry.target as HTMLElement).dataset.thumbPage)
            if (Number.isFinite(page)) request(page)
            observer?.unobserve(entry.target)
          }
        },
        { root: rail, rootMargin: THUMB_ROOT_MARGIN }
      )
      for (const node of rail.querySelectorAll("[data-thumb-page]")) {
        observer.observe(node)
      }
    } else if (rail) {
      // No observer support — fall back to rendering the first screenful.
      for (let page = 1; page <= Math.min(doc.numPages, 12); page += 1) request(page)
    }

    return () => {
      cancelled = true
      observer?.disconnect()
      for (const src of rendered.values()) releaseRasterUrl(src)
      rendered.clear()
    }
  }, [doc, railRef])

  return thumbs
}

export function PdfThumbRail({
  doc,
  pageIndex,
  open,
  onSelect,
}: {
  doc: PdfDocumentProxy | null
  pageIndex: number
  open: boolean
  onSelect: (pageIndex: number) => void
}) {
  if (!doc || !open) return null
  return <ThumbRailBody doc={doc} pageIndex={pageIndex} onSelect={onSelect} />
}

function ThumbRailBody({
  doc,
  pageIndex,
  onSelect,
}: {
  doc: PdfDocumentProxy
  pageIndex: number
  onSelect: (pageIndex: number) => void
}) {
  const railRef = useRef<HTMLDivElement | null>(null)
  const thumbs = usePdfThumbnails({ doc, railRef })

  useEffect(() => {
    railRef.current
      ?.querySelector(`[data-thumb-page="${pageIndex + 1}"]`)
      ?.scrollIntoView({ block: "nearest" })
  }, [pageIndex])

  return (
    <div
      ref={railRef}
      className="hidden w-28 shrink-0 flex-col gap-2 overflow-y-auto overscroll-contain border-r pr-2 sm:flex"
      role="navigation"
      aria-label="Page thumbnails"
    >
      {Array.from({ length: doc.numPages }, (_, index) => {
        const page = index + 1
        const src = thumbs.get(page)
        const current = index === pageIndex
        return (
          <button
            key={page}
            type="button"
            data-thumb-page={page}
            data-book-preview-press
            aria-current={current ? "page" : undefined}
            aria-label={`Page ${page}`}
            onClick={() => onSelect(index)}
            className={cn(
              "flex flex-col items-center gap-1 rounded-md p-1 outline-none transition-colors",
              current
                ? "bg-accent ring-1 ring-foreground/30"
                : "hover:bg-muted/60 focus-visible:bg-muted/60"
            )}
          >
            <span className="block w-full overflow-hidden rounded-sm border bg-background">
              {src ? (
                // Locally generated object URL — next/image cannot help here.
                // eslint-disable-next-line @next/next/no-img-element
                <img
                  src={src}
                  alt=""
                  draggable={false}
                  loading="lazy"
                  decoding="async"
                  className="block h-auto w-full"
                />
              ) : (
                <span className="block aspect-[3/4] w-full animate-pulse bg-muted/60" />
              )}
            </span>
            <span
              className={cn(
                "font-mono text-[10px]",
                current ? "text-foreground" : "text-muted-foreground"
              )}
            >
              {page}
            </span>
          </button>
        )
      })}
    </div>
  )
}

"use client"

import { extractPdfPageText, type PdfDocumentProxy } from "../pdf-runtime"

export type PdfSearchHit = {
  /** 1-based page number. */
  page: number
  /** Occurrences of the query on that page. */
  count: number
}

export function countOccurrences(haystack: string, needle: string): number {
  if (!needle) return 0
  let count = 0
  let from = 0
  for (;;) {
    const hit = haystack.indexOf(needle, from)
    if (hit === -1) return count
    count += 1
    from = hit + needle.length
  }
}

/**
 * Page-text index for in-document search.
 *
 * Text is extracted per page and cached for the document's lifetime, so the
 * first query costs one pass over the file and later queries are free. The
 * sequential walk yields between pages, which keeps the UI responsive on
 * long documents; `isCancelled` lets a new query abandon the walk early.
 */
export function createPdfSearchIndex(doc: PdfDocumentProxy) {
  const cache = new Map<number, Promise<string>>()

  const pageText = (pageNumber: number): Promise<string> => {
    const cached = cache.get(pageNumber)
    if (cached) return cached
    const task = doc
      .getPage(pageNumber)
      .then((page) => extractPdfPageText(page))
      .catch(() => "")
    cache.set(pageNumber, task)
    return task
  }

  const search = async (
    query: string,
    isCancelled: () => boolean
  ): Promise<PdfSearchHit[]> => {
    const needle = query.trim().toLowerCase()
    if (!needle) return []
    const hits: PdfSearchHit[] = []
    for (let page = 1; page <= doc.numPages; page += 1) {
      if (isCancelled()) return []
      const text = await pageText(page)
      if (isCancelled()) return []
      const count = countOccurrences(text.toLowerCase(), needle)
      if (count > 0) hits.push({ page, count })
    }
    return hits
  }

  return { search, pageText }
}

export const PDF_SEARCH_HIT_ATTR = "data-pdf-search-hit"

/**
 * Marks every text-layer span intersecting a query match. Spans carry one
 * text item each, so a phrase can straddle several spans — offsets are
 * accumulated over the concatenated text so all of them light up, the same
 * way the browser's own find highlights a range.
 */
export function highlightTextLayer(container: HTMLElement, query: string): number {
  const needle = query.trim().toLowerCase()
  const spans = Array.from(
    container.querySelectorAll<HTMLElement>("span:not(.markedContent)")
  )
  for (const span of spans) span.removeAttribute(PDF_SEARCH_HIT_ATTR)
  if (!needle) return 0

  let text = ""
  const offsets: { start: number; end: number; el: HTMLElement }[] = []
  for (const span of spans) {
    const content = span.textContent ?? ""
    offsets.push({ start: text.length, end: text.length + content.length, el: span })
    text += content
  }
  const haystack = text.toLowerCase()

  let total = 0
  let from = 0
  for (;;) {
    const hit = haystack.indexOf(needle, from)
    if (hit === -1) break
    const hitEnd = hit + needle.length
    for (const { start, end, el } of offsets) {
      if (end > hit && start < hitEnd) el.setAttribute(PDF_SEARCH_HIT_ATTR, "")
    }
    total += 1
    from = hitEnd
  }
  return total
}

"use client"

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type PointerEvent as ReactPointerEvent,
} from "react"
import {
  ChevronDownIcon,
  ChevronUpIcon,
  PanelLeftIcon,
  SearchIcon,
  XIcon,
  ZoomInIcon,
  ZoomOutIcon,
} from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Spinner } from "@/components/ui/spinner"
import { DEFAULT_CAPABILITIES } from "../capabilities"
import { useStableHandler } from "../hooks/use-stable-handler"
import { useBookPreview } from "../book-preview-provider"
import { readBookPreviewPrefs, writeBookPreviewPrefs } from "../prefs"
import {
  loadPdfDocument,
  renderPdfPageToCanvas,
  renderPdfTextLayer,
  resolvePdfOutline,
  type PdfDocumentProxy,
  type PdfLoadResult,
} from "../pdf-runtime"
import type { BookPreviewCapabilities, BookPreviewEngineProps, NormalizedBookSource } from "../types"
import {
  createPdfSearchIndex,
  highlightTextLayer,
  PDF_SEARCH_HIT_ATTR,
  type PdfSearchHit,
} from "./pdf-search"
import { PdfThumbRail } from "./pdf-thumb-rail"

// A zoom of 0 is the fit-width sentinel: the real scale is derived per page
// from the live scroller width, so phones and mixed-orientation documents
// open readable instead of pre-panned.
const PDF_FIT_ZOOM = 0
const PDF_MIN_ZOOM = 0.5
const PDF_MAX_ZOOM = 4
const PDF_STAGE_PAD = 32
// Finger-drag smaller than this still counts as a tap, not a pan.
const TOUCH_PAN_SLOP_PX = 6

function clampZoom(value: number): number {
  return Math.min(PDF_MAX_ZOOM, Math.max(PDF_MIN_ZOOM, value))
}

function engineCapabilities(source: NormalizedBookSource): BookPreviewCapabilities {
  return {
    ...DEFAULT_CAPABILITIES,
    zoom: true,
    search: true,
    thumbnails: true,
    upload: source.allowPdfUpload,
    download: Boolean(source.downloadUrl || source.pdfUrl),
    appearance: false,
    sound: false,
  }
}

export default function PdfEngine({
  source,
  pageIndex,
  persistPreferences,
  onPageChange,
  onReady,
  onError,
}: BookPreviewEngineProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null)
  const textLayerRef = useRef<HTMLDivElement | null>(null)
  const scrollRef = useRef<HTMLDivElement | null>(null)
  const stageInnerRef = useRef<HTMLDivElement | null>(null)
  const searchInputRef = useRef<HTMLInputElement | null>(null)
  const docTaskRef = useRef<PdfLoadResult["task"] | null>(null)
  const [pdf, setPdf] = useState<PdfDocumentProxy | null>(null)
  const [zoom, setZoom] = useState(PDF_FIT_ZOOM)
  const [fitted, setFitted] = useState(1)
  const [fitTick, setFitTick] = useState(0)
  const fittedRef = useRef(1)
  const zoomRef = useRef(PDF_FIT_ZOOM)
  const zoomHydratedRef = useRef(false)
  const pageIndexRef = useRef(pageIndex)
  const reportReady = useStableHandler(onReady)
  const reportError = useStableHandler(onError)
  const reportPageChange = useStableHandler(onPageChange)
  const { engineShortcutsRef } = useBookPreview()

  const [searchOpen, setSearchOpen] = useState(false)
  const [query, setQuery] = useState("")
  const [hits, setHits] = useState<PdfSearchHit[] | null>(null)
  const [hitIndex, setHitIndex] = useState(0)
  const [searching, setSearching] = useState(false)
  const [thumbsOpen, setThumbsOpen] = useState(false)
  const activeQueryRef = useRef("")
  const pendingHitScrollRef = useRef(false)

  // Touch pan/pinch state. Pointer Events are the only portable way to drive
  // pinch on a scroll container: browsers claim two-finger gestures before a
  // site sees them, so the stage takes touch-action:none and pans manually.
  const pointersRef = useRef(new Map<number, { x: number; y: number }>())
  const panRef = useRef<{ x: number; y: number; moved: boolean } | null>(null)
  const pinchRef = useRef<{
    startDist: number
    startMid: { x: number; y: number }
    /** Pinch midpoint in inner-element coordinates, captured at gesture start. */
    m: { x: number; y: number }
    baseZoom: number
    lastScale: number
    lastMid: { x: number; y: number }
  } | null>(null)
  const pinchCommitRef = useRef<{
    scale: number
    m: { x: number; y: number }
    target: { x: number; y: number }
  } | null>(null)

  useEffect(() => {
    zoomRef.current = zoom
  }, [zoom])

  useEffect(() => {
    pageIndexRef.current = pageIndex
  }, [pageIndex])

  const clearGesture = useCallback(() => {
    pointersRef.current.clear()
    panRef.current = null
    pinchRef.current = null
    // A pending pinch commit needs its transform left in place — it is what
    // keeps the pinch point glued under the fingers until the re-rendered
    // page paints and applyPinchCommit takes over.
    const inner = stageInnerRef.current
    if (inner && !pinchCommitRef.current) inner.style.transform = ""
  }, [])

  useEffect(() => {
    let cancelled = false
    let doc: PdfDocumentProxy | null = null

    async function open() {
      if (!source.pdfUrl && !source.allowPdfUpload) {
        reportError({
          kind: "invalid-source",
          message: "Provide a PDF URL or enable uploads.",
        })
        return
      }
      if (!source.pdfUrl) {
        reportReady({
          totalPages: 0,
          capabilities: {
            ...DEFAULT_CAPABILITIES,
            upload: true,
            zoom: true,
            appearance: false,
            sound: false,
          },
        })
        return
      }
      try {
        const loaded = await loadPdfDocument(source.pdfUrl)
        if (cancelled) {
          await loaded.task.destroy()
          return
        }
        docTaskRef.current = loaded.task
        doc = loaded.doc
        setPdf(doc)
        // A new document always opens at fit-width unless the reader has a
        // remembered zoom preference.
        if (persistPreferences) {
          const stored = readBookPreviewPrefs().pdfZoom
          setZoom(
            typeof stored === "number" && stored > 0 ? clampZoom(stored) : PDF_FIT_ZOOM
          )
        } else {
          setZoom(PDF_FIT_ZOOM)
        }
        zoomHydratedRef.current = true
        reportReady({
          totalPages: doc.numPages,
          capabilities: engineCapabilities(source),
        })
      } catch {
        if (!cancelled) {
          reportError({ kind: "pdf-parse", message: "This PDF could not be opened." })
        }
      }
    }

    void open()
    return () => {
      cancelled = true
      void docTaskRef.current?.destroy()
      docTaskRef.current = null
      setPdf(null)
    }
  }, [
    persistPreferences,
    reportError,
    reportReady,
    source.allowPdfUpload,
    source.downloadUrl,
    source.pdfUrl,
    source,
  ])

  // The author's outline becomes the reader's table of contents. Reported in
  // a second ready call so a slow bookmark walk never delays the first page.
  useEffect(() => {
    if (!pdf) return
    let cancelled = false
    void resolvePdfOutline(pdf).then((contents) => {
      if (cancelled || contents.length === 0) return
      reportReady({
        totalPages: pdf.numPages,
        capabilities: engineCapabilities(source),
        contents,
      })
    })
    return () => {
      cancelled = true
    }
  }, [pdf, reportReady, source])

  // A fresh document gets a fresh search index — cached page text would point
  // at pages of the previous file — and the search state resets with it.
  const searchIndex = useMemo(() => (pdf ? createPdfSearchIndex(pdf) : null), [pdf])
  const [prevPdf, setPrevPdf] = useState(pdf)
  if (prevPdf !== pdf) {
    setPrevPdf(pdf)
    setHits(null)
    setHitIndex(0)
    setSearching(false)
    setQuery("")
  }

  const needle = query.trim()
  useEffect(() => {
    activeQueryRef.current = needle
  }, [needle])
  // A changed query invalidates the previous result list immediately — the
  // async search lands later, and stepping through stale hits would jump to
  // matches for text that is no longer being looked for.
  const [prevNeedle, setPrevNeedle] = useState(needle)
  if (prevNeedle !== needle) {
    setPrevNeedle(needle)
    setHits(null)
    setHitIndex(0)
  }
  const activeHits = needle ? hits : null

  // Find-as-you-type: debounce keystrokes, then walk pages in order. The walk
  // yields between pages and bails on the next query or unmount. The cursor
  // jump happens inside the async result so landing on a hit is atomic with
  // the list that produced it.
  useEffect(() => {
    if (!searchIndex || !needle) {
      const layer = textLayerRef.current
      if (layer) highlightTextLayer(layer, "")
      return
    }
    let cancelled = false
    const timer = window.setTimeout(() => {
      setSearching(true)
      void searchIndex.search(needle, () => cancelled).then((nextHits) => {
        if (cancelled) return
        setSearching(false)
        setHits(nextHits)
        if (nextHits.length === 0) {
          setHitIndex(0)
          return
        }
        const after = nextHits.findIndex((hit) => hit.page > pageIndexRef.current + 1)
        const start = after >= 0 ? after : 0
        setHitIndex(start)
        pendingHitScrollRef.current = true
        reportPageChange(nextHits[start].page - 1, "instant")
      })
    }, 200)
    return () => {
      cancelled = true
      window.clearTimeout(timer)
    }
  }, [needle, searchIndex, reportPageChange])

  const stepHit = useCallback(
    (direction: 1 | -1) => {
      if (!activeHits || activeHits.length === 0) return
      const next = (hitIndex + direction + activeHits.length) % activeHits.length
      setHitIndex(next)
      pendingHitScrollRef.current = true
      reportPageChange(activeHits[next].page - 1, "instant")
    },
    [activeHits, hitIndex, reportPageChange]
  )

  const openSearch = useCallback(() => setSearchOpen(true), [])

  // Focus follows the open state rather than a microtask, which has no
  // ordering guarantee against the render that mounts the input.
  useEffect(() => {
    if (searchOpen) searchInputRef.current?.focus()
  }, [searchOpen])

  // In fit mode a container resize is a zoom change.
  useEffect(() => {
    const node = scrollRef.current
    if (!node || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(() => {
      if (zoomRef.current === PDF_FIT_ZOOM) setFitTick((tick) => tick + 1)
    })
    observer.observe(node)
    return () => observer.disconnect()
  }, [])

  // A remembered zoom is only written once the open() effect has applied the
  // stored value — otherwise mount would clobber the store with the default.
  useEffect(() => {
    if (!persistPreferences || !zoomHydratedRef.current) return
    writeBookPreviewPrefs({ pdfZoom: zoom })
  }, [persistPreferences, zoom])

  // The engine owns zoom/search state, so it registers handlers the shell's
  // keydown listener can invoke (+, -, 0, / and mod+F). Cleared on unmount.
  useEffect(() => {
    const ref = engineShortcutsRef
    ref.current = {
      zoomIn: () =>
        setZoom(clampZoom((zoomRef.current > 0 ? zoomRef.current : fittedRef.current) + 0.25)),
      zoomOut: () =>
        setZoom(clampZoom((zoomRef.current > 0 ? zoomRef.current : fittedRef.current) - 0.25)),
      zoomReset: () => setZoom(PDF_FIT_ZOOM),
      search: openSearch,
    }
    return () => {
      ref.current = {}
    }
  }, [engineShortcutsRef, openSearch])

  // Re-centers the view after a pinch commits: the transform held the pinch
  // point under the fingers while the old render was up; once the new scale
  // paints, scroll so the same document point lands at the finger midpoint.
  const applyPinchCommit = useCallback(() => {
    const commit = pinchCommitRef.current
    const inner = stageInnerRef.current
    const scroller = scrollRef.current
    pinchCommitRef.current = null
    if (!commit || !inner || !scroller) return
    inner.style.transform = ""
    const rect = inner.getBoundingClientRect()
    scroller.scrollLeft += rect.left + commit.m.x * commit.scale - commit.target.x
    scroller.scrollTop += rect.top + commit.m.y * commit.scale - commit.target.y
  }, [])

  useEffect(() => {
    if (!pdf || !canvasRef.current) return
    let cancelled = false
    let renderTask: { promise: Promise<void>; cancel: () => void } | null = null
    const documentProxy = pdf
    const textLayerEl = textLayerRef.current

    let textLayer: { cancel: () => void } | null = null

    async function draw() {
      try {
        const page = await documentProxy.getPage(pageIndex + 1)
        if (cancelled || !canvasRef.current) return
        const canvas = canvasRef.current
        // The fit scale uses this page's own base size, so a landscape figure
        // inside a portrait document still reads edge to edge.
        const base = page.getViewport({ scale: 1 })
        const hostWidth = Math.max(
          240,
          (scrollRef.current?.clientWidth ?? base.width) - PDF_STAGE_PAD
        )
        const fit = Math.min(3, Math.max(0.4, hostWidth / base.width))
        fittedRef.current = fit
        setFitted(fit)
        const effective = zoom > 0 ? zoom : fit
        renderTask = renderPdfPageToCanvas({
          page,
          canvas,
          scale: effective,
          // 3x DPR turns a page into a ~30MP bitmap; 2x is the point of
          // diminishing returns for reading.
          pixelRatio:
            typeof window === "undefined"
              ? 1
              : Math.min(2, Math.max(1, window.devicePixelRatio || 1)),
        })
        await renderTask.promise
        if (cancelled) return
        // A pinch that committed during this render resolves its scroll
        // position against the freshly sized page.
        applyPinchCommit()
        // Selectable text belongs on the flat reader: the canvas here is
        // static, so real spans can sit exactly over it.
        const container = textLayerEl
        if (cancelled || !container) return
        container.replaceChildren()
        container.style.width = canvas.style.width
        container.style.height = canvas.style.height
        // PDF.js positions every span against this factor.
        container.style.setProperty("--total-scale-factor", String(effective))
        textLayer = await renderPdfTextLayer({ page, container, scale: effective })
        if (cancelled) return
        const needle = activeQueryRef.current
        if (needle) {
          highlightTextLayer(container, needle)
          if (pendingHitScrollRef.current) {
            pendingHitScrollRef.current = false
            container
              .querySelector(`[${PDF_SEARCH_HIT_ATTR}]`)
              ?.scrollIntoView({ block: "center" })
          }
        }
      } catch (error) {
        const named = error as { name?: string }
        if (named.name !== "RenderingCancelledException" && !cancelled) {
          reportError({ kind: "pdf-render", message: "This page could not be rendered." })
        }
      }
    }

    void draw()
    return () => {
      cancelled = true
      renderTask?.cancel()
      textLayer?.cancel()
      textLayerEl?.replaceChildren()
    }
  }, [applyPinchCommit, pageIndex, pdf, reportError, zoom, fitTick])

  // A page change invalidates an uncommitted pinch — declared before the
  // gesture reset so the commit is already gone when that cleanup runs and
  // the stale transform gets cleared with it.
  useEffect(() => {
    return () => {
      pinchCommitRef.current = null
    }
  }, [pageIndex])

  // A page change mid-gesture leaves the transform/pointers pointing at a
  // page that is gone — reset both. Zoom is a dependency too so a button or
  // keyboard zoom clears a live transform, but the pinch *commit* survives:
  // a pinch's own setZoom is what re-renders, and the draw effect consumes
  // the commit to re-center.
  useEffect(() => {
    return () => clearGesture()
  }, [clearGesture, pageIndex, zoom])

  // Ctrl+wheel (and trackpad pinch, which browsers surface as ctrl+wheel) zooms
  // the document instead of scrolling. Needs a non-passive native listener.
  useEffect(() => {
    const node = scrollRef.current
    if (!node) return
    const onWheel = (event: WheelEvent) => {
      if (!event.ctrlKey) return
      event.preventDefault()
      const current = zoomRef.current > 0 ? zoomRef.current : fittedRef.current
      setZoom(clampZoom(current - Math.sign(event.deltaY) * 0.15))
    }
    node.addEventListener("wheel", onWheel, { passive: false })
    return () => node.removeEventListener("wheel", onWheel)
  }, [])

  const onStagePointerDown = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    if (event.pointerType !== "touch") return
    event.currentTarget.setPointerCapture(event.pointerId)
    pointersRef.current.set(event.pointerId, { x: event.clientX, y: event.clientY })
    if (pointersRef.current.size === 2) {
      const [a, b] = Array.from(pointersRef.current.values())
      const mid = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 }
      const rect = stageInnerRef.current?.getBoundingClientRect()
      pinchRef.current = {
        startDist: Math.max(1, Math.hypot(a.x - b.x, a.y - b.y)),
        startMid: mid,
        m: rect ? { x: mid.x - rect.left, y: mid.y - rect.top } : { x: 0, y: 0 },
        baseZoom: zoomRef.current > 0 ? zoomRef.current : fittedRef.current,
        lastScale: 1,
        lastMid: mid,
      }
      panRef.current = null
      return
    }
    if (pointersRef.current.size === 1) {
      panRef.current = { x: event.clientX, y: event.clientY, moved: false }
    }
  }, [])

  const onStagePointerMove = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    const point = pointersRef.current.get(event.pointerId)
    if (!point) return
    point.x = event.clientX
    point.y = event.clientY
    const pinch = pinchRef.current
    const inner = stageInnerRef.current
    if (pinch && inner && pointersRef.current.size >= 2) {
      const [a, b] = Array.from(pointersRef.current.values())
      const dist = Math.hypot(a.x - b.x, a.y - b.y)
      const mid = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 }
      // Live scale is clamped to the zoom range with slight overshoot so the
      // gesture feels responsive at the edges without overshooting on commit.
      const scale = Math.min(
        (PDF_MAX_ZOOM * 1.05) / pinch.baseZoom,
        Math.max((PDF_MIN_ZOOM * 0.9) / pinch.baseZoom, dist / pinch.startDist)
      )
      pinch.lastScale = scale
      pinch.lastMid = mid
      const dx = mid.x - pinch.startMid.x
      const dy = mid.y - pinch.startMid.y
      const m = pinch.m
      // Scale around the pinch midpoint and let the fingers drag it — the
      // old render stays put until the commit re-renders at the final zoom.
      inner.style.transform = `translate3d(${m.x * (1 - scale) + dx}px, ${m.y * (1 - scale) + dy}px, 0) scale(${scale})`
      return
    }
    const pan = panRef.current
    const scroller = scrollRef.current
    if (pan && scroller && pointersRef.current.size === 1) {
      const dx = event.clientX - pan.x
      const dy = event.clientY - pan.y
      if (!pan.moved && Math.hypot(dx, dy) < TOUCH_PAN_SLOP_PX) return
      pan.moved = true
      pan.x = event.clientX
      pan.y = event.clientY
      scroller.scrollLeft -= dx
      scroller.scrollTop -= dy
    }
  }, [])

  const onStagePointerEnd = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      pointersRef.current.delete(event.pointerId)
      const pinch = pinchRef.current
      if (pinch && pointersRef.current.size < 2) {
        pinchRef.current = null
        const finalZoom = clampZoom(pinch.baseZoom * pinch.lastScale)
        const rendered = zoomRef.current > 0 ? zoomRef.current : fittedRef.current
        pinchCommitRef.current = {
          scale: finalZoom / pinch.baseZoom,
          m: pinch.m,
          target: pinch.lastMid,
        }
        if (Math.abs(finalZoom - rendered) < 0.001) {
          // No re-render is coming — settle the scroll position now.
          applyPinchCommit()
        } else {
          setZoom(finalZoom)
        }
      }
      // A remaining finger can keep panning after the other lifts.
      const remaining = Array.from(pointersRef.current.values())[0]
      panRef.current = remaining ? { ...remaining, moved: true } : null
    },
    [applyPinchCommit]
  )

  const effectiveZoom = zoom > 0 ? zoom : fitted
  const hitCount = activeHits?.length ?? 0

  return (
    <div className="flex h-full w-full flex-col gap-3 p-4">
      <div className="flex flex-wrap items-center justify-center gap-2">
        <p className="max-w-[10rem] truncate text-xs text-muted-foreground sm:max-w-none">
          {source.pdfFileName ?? "Document"}
        </p>
        {searchOpen ? (
          <div className="flex items-center gap-1">
            <div className="relative">
              <SearchIcon className="pointer-events-none absolute top-1/2 left-2 size-3.5 -translate-y-1/2 text-muted-foreground" />
              <Input
                ref={searchInputRef}
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                placeholder="Search document"
                aria-label="Search document"
                className="h-8 w-40 pl-7 text-xs sm:w-52"
                onKeyDown={(event) => {
                  if (event.key === "Enter") {
                    event.preventDefault()
                    stepHit(event.shiftKey ? -1 : 1)
                  }
                  if (event.key === "Escape") {
                    event.preventDefault()
                    setQuery("")
                    setSearchOpen(false)
                    event.currentTarget.blur()
                  }
                }}
              />
            </div>
            <span className="min-w-[4.5ch] text-center font-mono text-xs text-muted-foreground" aria-live="polite">
              {searching ? "…" : activeHits ? (hitCount === 0 ? "0" : `${hitIndex + 1}/${hitCount}`) : ""}
            </span>
            <Button
              type="button"
              variant="ghost"
              size="icon-sm"
              aria-label="Previous match"
              disabled={hitCount === 0}
              onClick={() => stepHit(-1)}
              data-book-preview-press
            >
              <ChevronUpIcon />
            </Button>
            <Button
              type="button"
              variant="ghost"
              size="icon-sm"
              aria-label="Next match"
              disabled={hitCount === 0}
              onClick={() => stepHit(1)}
              data-book-preview-press
            >
              <ChevronDownIcon />
            </Button>
            <Button
              type="button"
              variant="ghost"
              size="icon-sm"
              aria-label="Close search"
              onClick={() => {
                setQuery("")
                setSearchOpen(false)
              }}
              data-book-preview-press
            >
              <XIcon />
            </Button>
          </div>
        ) : (
          <Button
            type="button"
            variant="ghost"
            size="icon-sm"
            aria-label="Search document"
            aria-keyshortcuts="/ Control+F"
            onClick={openSearch}
            data-book-preview-press
            className="min-h-11 min-w-11 sm:min-h-7 sm:min-w-7"
          >
            <SearchIcon />
          </Button>
        )}
        <Button
          type="button"
          variant="ghost"
          size="icon-sm"
          aria-label="Zoom out"
          onClick={() => setZoom(clampZoom(effectiveZoom - 0.25))}
          data-book-preview-press
          className="min-h-11 min-w-11 sm:min-h-7 sm:min-w-7"
        >
          <ZoomOutIcon />
        </Button>
        <span className="font-mono text-xs text-muted-foreground">
          {zoom === PDF_FIT_ZOOM
            ? `Fit ${Math.round(effectiveZoom * 100)}%`
            : `${Math.round(zoom * 100)}%`}
        </span>
        <Button
          type="button"
          variant="ghost"
          size="icon-sm"
          aria-label="Zoom in"
          onClick={() => setZoom(clampZoom(effectiveZoom + 0.25))}
          data-book-preview-press
          className="min-h-11 min-w-11 sm:min-h-7 sm:min-w-7"
        >
          <ZoomInIcon />
        </Button>
        <Button
          type="button"
          variant={zoom === PDF_FIT_ZOOM ? "secondary" : "ghost"}
          size="sm"
          aria-pressed={zoom === PDF_FIT_ZOOM}
          aria-label="Fit page width"
          onClick={() => setZoom(PDF_FIT_ZOOM)}
          data-book-preview-press
        >
          Fit
        </Button>
        {pdf && docHasMultiplePages(pdf) ? (
          <Button
            type="button"
            variant={thumbsOpen ? "secondary" : "ghost"}
            size="icon-sm"
            aria-label="Page thumbnails"
            aria-pressed={thumbsOpen}
            onClick={() => setThumbsOpen((open) => !open)}
            data-book-preview-press
            className="min-h-11 min-w-11 sm:min-h-7 sm:min-w-7"
          >
            <PanelLeftIcon />
          </Button>
        ) : null}
      </div>
      <div className="flex min-h-0 flex-1 overflow-hidden rounded-lg border bg-muted/30">
        <PdfThumbRail
          doc={pdf}
          pageIndex={pageIndex}
          open={thumbsOpen}
          onSelect={(index) => reportPageChange(index, "instant")}
        />
        <div
          ref={scrollRef}
          className="flex min-h-0 flex-1 overflow-auto p-4"
          onDoubleClick={() => {
            // A double-click that selected a word is a selection gesture,
            // not a zoom request — the text layer stays in charge.
            if (typeof window !== "undefined" && window.getSelection()?.toString()) return
            setZoom((current) =>
              current === PDF_FIT_ZOOM ? clampZoom(fittedRef.current * 1.75) : PDF_FIT_ZOOM
            )
          }}
        >
          {!pdf ? (
            <div className="m-auto flex items-center gap-2 text-sm text-muted-foreground">
              <Spinner />
              {source.allowPdfUpload ? "Upload or drop a PDF to begin" : "Waiting for a document"}
            </div>
          ) : (
            /* Auto margins center a page that fits and let a zoomed page scroll
               to every edge — justify-center would clip the start side. The
               canvas keeps its exact rendered size so the text layer can sit
               precisely on top. touch-action:none hands touch panning and
               pinch to the pointer handlers above. */
            <div
              ref={stageInnerRef}
              className="relative m-auto shrink-0"
              // Origin 0 0 makes the live pinch transform an exact
              // scale-around-midpoint; the default center origin would drift.
              style={{ touchAction: "none", transformOrigin: "0 0" }}
              onPointerDown={onStagePointerDown}
              onPointerMove={onStagePointerMove}
              onPointerUp={onStagePointerEnd}
              onPointerCancel={onStagePointerEnd}
            >
              <canvas
                ref={canvasRef}
                role="img"
                aria-label={`Page ${pageIndex + 1}`}
                className="block rounded bg-background shadow"
              />
              <div ref={textLayerRef} className="textLayer" data-book-preview-text-layer />
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

function docHasMultiplePages(doc: PdfDocumentProxy): boolean {
  return doc.numPages > 1
}
